) AS (
  VALUES 
    (500::BIGINT, 'Es un profé bastante carismatico, no se guía por una presentación, realiza bastante ejercicios en clase y deja tareas super faciles y regala practicamente 10% de la nota solo por hacer las tareas, responde las dudas y sus clases son divertidas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-07-28T00:00:00+00:00'::TIMESTAMPTZ, '56530ea52541a096588c8047e0372a487f19dd9048de38301ac3d28642cbf268'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Hay ser autodidacta porque en clase no explica, solo hace ejercicios. Pero es un buen profesor y una increíble persona, bastante agradable y ayuda en horas de consulta. Deja tareas de Khan Academy y quices solo por ir, si necesita ayuda el final puede que se la dé, la verdad lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ab9bd62c0544b56a85546cfa16d66d364d2cd7370affd2a035538f5aa7db944a'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Nunca encontré a un profe tan agradable, más allá de su calidad como profesor(Que es buena, tomar a consideración que hace muchos ejercicios y que a veces uno puede perderse). Es un buen ser humano, después de clases se iba a jugar poker o Catan con nosotros.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, '45b87927b9154ed5ce203fb4308f83e87fc8a78663d91d6aab7585acbb46ce9d'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Es buen profesor pero explica a veces extraño y no prepara para examenes. Dejo quices semanales que son hechos en clase y a menudo en pareja o grupo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'eaaa6f005642654ab14522938bb1dc711690de1d7dd9df6209489352130097f6'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'El profe explica bien, las clases no eran largas y hacía puros ejercicios. Eso sí, había que ser bastante autodidacta. Pero en general, es buena nota y califica bastante justo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'bb2ddaa52e3534955193571d274bdb568d5ef2d79d7c934ad49383a3d37e2c17'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'El curso fue semipresencial, por lo que uno tenía que aprender la mayoría de la materia por cuenta propia, dejo 2 examenes de 35% y el 30% de evaluaciones especificas practicamente lo regaló, no califica tan duro pero a la hora de calificar no pone decimales. Es buena opción para repitentes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'a2ecae5024880e4dc0bdbb0d8ecc9ae376bf434acd592511c194f8a57135f7f4'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Muy buen profe, explica bien pero la materia si puede ser difícil de entender y a veces uno se puede perder por eso. Lo malo es que si dura mucho en calificar exámenes y quices, era semana 17 y no teníamos las notas actualizadas. Pero aparte de eso cae bien y es gracioso, si uno tiene dudas lo ayuda'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '8e6054c7e26a4142f7bff8bb902982c45760d6c5e905c02a08374901bed7e1c0'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Llevé CAL por segunda vez con él, siento que es un buen profe pero a veces no explica directamente lo que es necesario para los examenes. Tarda mucho en subir notas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c409c717c24aebec4da13b3521d58c4f1ea715f8d1a43c279599b0362422b944'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Muyu buen profesor explica bastante bien, realiza bastante practica, eso si a que poner atención, pero sus clases son bastante buenas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'f4bf091cdb74699c2fe1b0837a0c45415cb0f619a4a591a231571d0092932d39'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Dura mucho en calificar y no da la materia que sale en os exámenes'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9094571f35a3acd755d4a41f77d38fa530f9ddbfc04b4dff308da58d9a56b23b'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Un buen profesor, explica muy claro y ayuda en todo lo que el estudiante le solicite. Si les cuesta la mate con él pasa de fijo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, '002bb7a7c106d97c8f0db7e849c832fd98364c477622560923c2f191c8587c39'::TEXT, ARRAY[2444]::BIGINT[]),
    (500::BIGINT, 'Duró 2 meses en entregar el primer examen. Cancelaba las clases por partidos de fútbol. El segundo examen, faltando 15 minutos mandó el examen por correo y lo hizo virtual. Y para el tercer examen, solo hizo una clase y dió la materia, 3 semanas libres y aplicó el examen.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1d84e100f533e2bb112530af2b1ee5272658f69499f9bafc87cae338bbb177ab'::TEXT, ARRAY[2439]::BIGINT[]),
    (500::BIGINT, 'Las clases se hacen un poco aburridas y hay que ponerle desde el principio solo de hacen 2 exámenes'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '97ac0a2f4f7c640bd963b042cb10b196c0d444ca2d9f1e9fc0181f0727149a7f'::TEXT, ARRAY[2444]::BIGINT[]),
    (500::BIGINT, 'El profe es buena gente y buen profesor. A veces va muy rapido con la materia, pero si uno le hace preguntas siempre te ayuda. Muy bagabundo y nunca pone las notas en el TEC digital. Nunca responde emails y mensajes. Asistencia es obligatoria y ss examenes estan en el intermedio de dificultad.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, '38f96a9399624040556ff4ed5a33b2a4aecb89451a19ac5db7cdeee64d0d6cdf'::TEXT, ARRAY[2444]::BIGINT[]),
    (500::BIGINT, 'Le ayuda a uno si se lo pide pero a veces las explicaciones son un poco vagas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'c38dc9977b06e3415f0c08840d84e4d03a2a22c9d4f5a7476c37a747828d3d15'::TEXT, ARRAY[2444]::BIGINT[]),
    (500::BIGINT, 'Pasé el curso hace un año, viendo a mi novia hacerlo me di cuenta que no era tan dificil pero que Paez no explicó tan bien ALGUNOS temas, va muy lento para la cantidad de materia que tiene álgebra, al final tiene que explicar muy rápido. Pero explica muy bien en general. No es ideal, pero es bueno.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'a9f314d0d0570b7cd4d88361ba420cf40e2b0dbd647da1e502cf95f2fca665ac'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e89de66fb1e2400287d20140e9dc6506cab54cac81be752d810a9dc6393bbdc6'::TEXT, ARRAY[2439]::BIGINT[]),
    (500::BIGINT, 'si es verano ni se les ocurra perder el tiempo solamente hace dos exámenes de 40% cada uno y realmente te mata con eso ademas de que los ejercicios de los exámenes no son iguales a los de la clase son muchísimo mas difícil, si se quiere no lo lleve. sin embargo si creo que explica muy bien.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2024-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'b49e60a54e1d417da4ad04e6ab0a3557855ca6bb71e2f88d215f4bac4612f1f5'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'Si es una persona estresada con los resultados no le recomiendo matricular con este profe porque las notas de todo las da la ultima semana, sin embargo las evaluaciones y trabajos que deja son bastantes sencillos en general y es facil pasar'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'e9ee31cab602952d2fdc89b9d84d5eda4cdfb232870530786e278d7797a58cd9'::TEXT, ARRAY[2444]::BIGINT[]),
    (500::BIGINT, 'Nunca había conocido profesor más desorganizado como este. 4 meses después nos dio la nota de un quiz. Llegamos al último parcial sin tener nada calificado (quices y tareas).'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, '8c8986c817add5b19ddd98b16794faaea7ba040026402d0ed61206ff3032b0c7'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Hace muy pocas evaluaciones entonces cada una vale demasiado al final, no queda claro que está haciendo en la pizarra, porque solo toma ejemplos de la materia y los resuelve sin explicar a fondo, asume que ya hiciste por completo las guías antes de la clase, y todos sabemos que no siempre da chance'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3369b188d0e932d7d038d2c00d2696e4fb5567c551c4ed969a52ffd65fc5ce11'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Pesimo docente. No sigue el reglamento. Califica cuando le da la gana, aplica tareas y las califica a ultimo momento. deszcortes y nada empatico. en sus clases resuelve ejemplos, pero no los explica. no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-02-01T00:00:00+00:00'::TIMESTAMPTZ, '5dcacb4f8be0d22b6120869e9940511c2084db3ac7ff2c5fa0bff085d0f5d846'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2f7e3b3b08e1d7cfe52555dba1f23cfe0d5ed28f23e929b32b463a56f8a09abe'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'Mal profe, solo resuelve algunos ejercicios, no explica la materia como tal y un poco odioso, no grababa las clases pero llegó a dejar una tarea y si usted no fue no tenía ni idea de lo que tenía que hacer No lleve con el!!!'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8a4102d24210af42138dbb591d38ea9bc4952ca55971d38f693e3c66cb291abf'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'En sus clases solo es resolución de ejercicios y la explicación de lo básico para resolver los más fáciles, no todos los graba porque es "complementario a las guías" y ya lo deberíamos haber estudiado. Tarda en contestar. Calificó todo hasta semana 18. Se molesta si no participan en clase.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '429193a7fb114e2cbfa18500eef557bc4491fb98f2414d8c29f2edb72f4de93d'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Las clases son resolución de ejercicios, algunas veces no realiza algunas evaluaciones y califica hasta las últimas semanas. Si es la primera vez que lleva el curso no lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2badda2e7ea964a8d047caf3aa4a24a680e226aa6352b551a62a89235af9d32b'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Es como un padre ausente.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '0fec68b6abeedad7197909bbcf1b0eb477723487540febd6f36514ece33e6e4b'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'No graba las clases, en las clases solo hace la resolución de problemas, es muy difícil contactarlo por mensaje ya que dura mucho tiempo en contestar. El curso es muy autodidacta ya que el profe deja las horas para que uno repase. Y la nota del curso lo da a conocer hasta el final.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '4ffed922a6b261dbef7c7c171e27f45aae12403808f8ee68c048f6a9612962a7'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'En virtual las clases son de resolución de ejercicios no explica la materia'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '9c5beb8d65d2484b906aafc01b6b05be76bdbcc60c5120fa9c5293091cebc028'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'No es buena opción para llevar el curso por primera vez, es un poco confuso en sus explicaciones, es muy desordenado con las evaluaciones, hasta el punto de no aplicarlas. Califica hasta semana 16 y es dificil contactarlo. Es curso es catedrático y sus evaluaciones requieren mucha preparación.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ffdd2f178914b5c03ccd586226503cc06a87385dd66a8ccc6f153ea0e9d5f9e3'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Hp se le queda corto para este "profesor" si es que se le puede llamar así, no graba clases, no explica bien y siempre va muy rápido, nunca está disponible (si usted le escribe le va contestando 4 o 5 días después), las calificaciones las pone hasta el puro final del curso. Malisimo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'c2d6404340d9e8794fd26ebfc9c46dc96fab702a35287f225d46f65159453a9a'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Muy irresponsable a la hora de calificar el hp'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'b123e64a53b5c0ba431cbbd9c7a115ee51f53490c003eb88e8db726e96eb1615'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'No graba las clases, lo manda a estudiar las guias, sus clases son "complementarias" a las guias. Es muy buen profe, explica con detalle. Los ejercicios que resulve son fáciles comparados al examen. Y muy lento en entregar notas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'cc19fd61e1cc457dd43007beb40f69b3d3a0c23e8acc80fc44cb73f2ee382c5f'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Muy irresponsable, un día antes del examen final del curso y a ningún estudiante nos había actualizado las notas. Increíble que terminando el semestre aún habían tareas sin calificación. El grupo entero solicitaba las notas y desde octubre nos llevó con el cuento de "pronto" o "para este fin"...'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7e22a639b93e6d9683cf6775ecf3fb7ac606e40c947355679eb1ca5372aee8f5'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Este profe no graba las clases, realiza los ejercicios más fáciles en clase y luego a uno se lo suenan en los exámenes y en los quices.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '8166106eb9d1f5f619af3faa3ce12fc29e592a077954018928c2bdd664cd6cbd'::TEXT, ARRAY[1018]::BIGINT[]),
    (500::BIGINT, 'Paez siempre manda a estudiar con las guías ya que sus clases solo son "complementarias" (ni las graba) así que hay que estudiar mucho por cuenta propia. Ayuda que el profe deja bastantes asignaciones a lo largo del semestre.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '6cdbad20a392a797da349763a2697bf50de4ec9593db8e694d2066da5991e1eb'::TEXT, ARRAY[2439, 563]::BIGINT[]),
    (500::BIGINT, 'El mejor profe de mate que he tenido hasta el momento, tomando en cuenta el colegio. Explica muy bien, el problema es que los cursos de matematica dependen de las guias, por lo que sus clases son mas que todo complementarias. Sus proyectos son muy fáciles. Si asiste debe de estar atento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'f5e2739e43f88601fafcacab5ef68953377916fc21dc81627059a927ee43b663'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Buen profe, ayuda mucho y en general buena nota'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'b5950cab72c4650699028149bc45e16b73b31dd1bc47ecd6cf19bf81ac5d648e'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Súper bueno , explica con detalle todo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '580eb2eedef31b72e873149e2ed56d002ae91d8ab938349c7c9d847f8e225d73'::TEXT, ARRAY[1641]::BIGINT[]),
    (500::BIGINT, 'Como dicen los comentarios de abajo no es mal profe tampoco el mejor. Pero él espera que usted le dedique bastante tiempo a estudiar por su cuenta las guías. Durante las clases él resuelve ciertos ejercicios los que resolvía explicaba claro. Las clases usualmente no eran largas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd81a1c779c088c7685d20df65fcbaa5b43c9dd7d7a81d89bca72c47f40eb1640'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'No graba las clases, no da explicaciones completas durante la clase por que "en la guía semanal viene todo". No es un mal profe, tampoco es excelente ni el mejor, si es una persona paciente lleve el curso con el :)'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-01-18T00:00:00+00:00'::TIMESTAMPTZ, '02be93c56192cd5e1ee9fd3a975c46b2298bc14fa840bcf9d968661131a1b560'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Es muy bueno, explica y ayuda mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '833014c7d8e8779b6ad195dc47b889cea798e11c4b34410261b6bba88002e1b0'::TEXT, ARRAY[1641]::BIGINT[]),
    (500::BIGINT, 'No explica bien, hace muchos enredos y va muy rápido. Lo que sale en los exámenes es MUY distinto a lo visto en clase. No volvería a tomar su clase de nuevo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '6d8d9cc7ac5ae915a6a2d5b8290201efb1c34bdbed8861eacd213f5c7bb074db'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Como profesor es excelente la verdad, explica muy bien, siempre trata de dejar claro la materia, tiene espacios de preguntas antes y después de la clase en esta modalidad virtual. Sin embargo, es un toque olvidadizo a la hora de subir algún documento o de revisar alguna tarea; muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '18ee381ff77934303a2201737610d406e72b7f0b80aa82da4a5bb7e8823eb2aa'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Muy buen profesor, te explica hasta que comprendas, y tiene horarios de consulta antes y despues de la leccion en la modalidad virtual. Inspira a estudiar...'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'e89fd454434723ee6931b63215342823d9d011cb7ce60acd9be589c4fee4f14d'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Se sabe TODA la materia del curso y la explica como los dioses. Maneja muy bien las plataformas virtuales, inspira confianza y es buena gente. Lo único es que muchas calificaciones las entrega hasta el final, pero bah, eso no opaca lo excelente que es!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '697ed19bf8438367929a287363a29dc2d9e719da52096e718785c62d7704a1e8'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Demasiado buen profe, explica muy bien ya que va al grano y es muy buena gente con el estudiante. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '6a39d5eeb6cf79e735a3d43083e2ad43b596d30013e18119fda61d196440b491'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Es excelente explicando y no entrego las notas de las tareas hasta ultima instancia pero luego de cada entrega realizo una revisión en la clase entonces te podes dar una idea de la nota de cada una y sabes si hiciste algo mal, dispuesto a aclarar dudas, si te cuesta un poco este profe es excelente'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '5c6b38cbc28469d3aa941ce87069b2f6b3af82d637c06e3893af653d8b35dfc8'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Muy bueno explicando y ayuda a los estudiantes. Un profe muy pura vida. Es muy desorganizado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '238c2502be67e63b3eff862681c859c4d0617ab10cca03bd0a8c83269dd97d70'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Cuando decidí matricular con él igual había leído que era un poco desorganizado, matriculé y SÍ, es totalmente desorganizado. Pero es muy buen profe y aclara todas las veces que sea necesario! Yo si llevaría otro curso con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'e39368d27d1bcd843a3c67fcffa37e5a8de3fb0c5efcf6656bf8da73f25d8313'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Un poco desorganizado a a hora de dar la materia, sin embargo explica bien y si uno tiene dudas las responde con gusto.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'a97ac0c8e041ede841002cd3b56eb93e18b7b29e207c6b9f56b4ab9d9547e418'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Es uno de los mejores profes de mate que he tenido, sabe bastante y lo transmite muy bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-26T00:00:00+00:00'::TIMESTAMPTZ, '89b1df1d6eb70d3638291745835f623390ce3bba54ac99aead5c8eb03041a33d'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'Muchos lo alaban por su gran conocimiento y es bueno impartiéndolo, pero como profe me pareció muy desorganizado. Nunca regresa los quices hasta el final del curso, entrega los exámenes super tarde entonces no sabes si vas a pasar el curso hasta el día antes de la repo, etc.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '9a32a5e8f213ee09607b95440b950bc2a878f69163384147c2e53dacd626b2cd'::TEXT, ARRAY[1041]::BIGINT[]),
    (500::BIGINT, 'Muy desordenado para dar la materia y para los trabajos'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-01-06T00:00:00+00:00'::TIMESTAMPTZ, '0ca877d6d9241038c2f1225ee1e562959d373032abeddadf6c245270e1b56e74'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'El profe es super buena nota, la clase a veces era un toque aburrida. El único problema era que duraba mucho entregando exámenes, pero en sí lo recomiendo, explica bien y todo lo que entró en los exámenes se vio en algún momento en clases'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-13T00:00:00+00:00'::TIMESTAMPTZ, '0e01442778b9d1d382c75b8be77e2021742be7e185c578d9274f4757518ceefe'::TEXT, ARRAY[1041]::BIGINT[]),
    (500::BIGINT, 'El profe es super buena nota, los quices y tareas prácticamente los regala. A veces se enreda un poco explicando pero si se le entiende y califica justo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'd2c3dece190644b16b5aefc0042b7c285df312d61fe32102d4d90d8730eb3551'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'El profe es muy buena nota. Dura mucho para entregar exámenes, hasta un mes se tarda, pero en sí él es bueno. Conoce bastante de la materia pero es un poco desorganizado, pero meta el curso con él, explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Pocos exámenes']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a4ff60ad66ae5215b81c4ba117e95d05872d2ad7bfdbf225a701fd4acdb6ec4a'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a8f02f9aaeaedca7e4de796c6ab3d65ccfcf560b69f0850c1acf2f0b2ff78ef8'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0f8362f6401c0b213c875b7bbbec1be9bf7613e7baa72247d01c64d17fead4d0'::TEXT, ARRAY[1041]::BIGINT[]),
    (500::BIGINT, 'Si vas a todas las clases vas a entender todo , es muy claro y atento a atender las dudas , no califica duro los exámenes pero dura un poco calificándolos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'da2883a3808b90095935c7fca1dd3d5787e547cfd11cf9e0894071640dc3e64b'::TEXT, ARRAY[1041]::BIGINT[]),
    (500::BIGINT, 'Muy buen profesor explica muy claro, lo recomendaría y tomaría sus cursos otra vez.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '07936eb20858e8833d4f38384e382b2094391d06e94cfe776321e36ac7b76db0'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'Es super relax'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '354e74be4713af919a7ebd4f49787a945c6541780805603c17ac6653c8d5bd34'::TEXT, ARRAY[103]::BIGINT[]),
    (500::BIGINT, 'Con solo ir a clases y poner atención, se pasa fácil los exámenes. Califica normal, ni suave ni rudo. Es muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '4cb42453d9213106e11d97b7117a40228ac494354f10d07317fc8beaa9f6c619'::TEXT, ARRAY[968]::BIGINT[]),
    (500::BIGINT, 'Da lo necesario en clase, depende de uno si estudia más o no. Los exámenes si son algo rudos. Es buena gente y da buenos recesos. Al final ayuda a los que verdaderamente fueron perseverantes y le pusieron en el curso.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2016-12-08T00:00:00+00:00'::TIMESTAMPTZ, '24f32c6fcbe44ab01d545b37d0f439033a75686b4d17b4596fbfba3b87ba3e83'::TEXT, ARRAY[103]::BIGINT[]),
    (500::BIGINT, 'Explica claro, atiende dudas y es pura vida, bromea y se rie cuando es necesario, además califica normal y se entiende la materia.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5893321a6b1d2aa05aa545c977d0dfa27caad53ad393e8aa111333c55abeac82'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Es buen profe, califica duro y a veces se enreda explicando pero en general es bueno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9f2f9ac3e81a1f1bdc9b5d92df02f4baf9c77c74731ebd6fa3905be6769e61f6'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Explica excelente y es muy pura vida. Califica entre regular y duro. Hace pocos quices y una tarea antes de cada examen. Muy buena opción.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'cebe5812b02a6277f95e01b7eb2d0068d3f7164f2fb6b1d42368b7bb6d5b18bf'::TEXT, ARRAY[1641]::BIGINT[]),
    (500::BIGINT, 'Explica bien pero no hace muchos ejemplos en clase, ni quices ni tareas. Si uno no hace su parte con lo que se hace en clase no es suficiente. Es vagabundo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, '4be511860da4dcc0aa24b74575ece2675dc80bffdb5bc94ddae072e8ff22f70b'::TEXT, ARRAY[634]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'fdfbe3c1d88473e7e8885b1dd6dc744b370c638a35fe68bf1adeb2f122be6b94'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-03-22T00:00:00+00:00'::TIMESTAMPTZ, '4bce880c1eba813f3007cd79ae295938719deb66d42f4b4a65b1a4ad198d5987'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'es un crack, si usted le pone y estudia lo necesario con el se hace muy facil!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, '07724dc38b7aef581101a881065030cec08c5646e6c77d0eb0b9cae04e47f44a'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, '214d43635050951b1cefa3a732563740bbac5dc31ffcedcb055e1a6e572e9972'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'De los mejores profes de la escuela, explica súper claro. Detalla de donde salen las cosas, lo que ayuda mucho para el razonamiento y análisis de la materia. Casi no hace quices, generalmente le gusta evaluar el porcentaje de quices y tareas en trabajo en clase (y en grupo :D) y una que otra tarea'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '761396a80ffc5d07f6645f8aa33b199b9581c2f23a02ef31e8f718fbe5024a45'::TEXT, ARRAY[1034]::BIGINT[]),
    (500::BIGINT, 'Para mate general es excelente, explica bien la materia y no hace falta que repita, pero si no entiendo el va y le aclara la duda, las clases están bien, prefiere que ud haga un ejercicio a que llegue a copiar mil, no califica tan rudo. Muy recomendado si para mate general. Es un crack.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e448eb5aa00aa3ecd22b78dde2992e905e360b93dc973099ad6bc05466ca912c'::TEXT, ARRAY[563]::BIGINT[]),
    (500::BIGINT, 'Para Álgebra el único contra que le veo es que a veces es muy quisquilloso con la simbología utilizada en los exámenes. Las clases llegaron a tornarse realmente aburridas con el tiempo y al profe no le molestaba ver a uno que otro dormido en plena clase. Explica claro y ayuda si es necesario.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, '7bdd2c04ee6be034b5890966da277c47ef751d9c26bfa356caaa00ae26dbbd4b'::TEXT, ARRAY[1041]::BIGINT[]),
    (500::BIGINT, 'Excelente en la manera de enseñar, explica las veces necesarias y ejemplos muy claros. Es cierto que a veces quita algunos puntos en el desarrollo de problemas pero siempre es pasable. Recomendado para Álgebra y Cálculo, para Discreta es bueno pero podría haber otro mejor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '48e132509056b5b9e90ee11ac93a1e274f153cff1bc5fd6808b32eb4e3c92a05'::TEXT, ARRAY[1018, 2920, 634]::BIGINT[]),
    (500::BIGINT, 'Siempre está disponible para horas de consulta y tiene un buen carisma para explicar la materia. No le molesta en absoluto que uno llegue a dormir a la clase. Además hace pocos quices y termina regalando los puntos :3'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '7ece9d3a6325493dccc190141c45b874acb7047e07a37c8ee7439efd3cd17a00'::TEXT, ARRAY[1641]::BIGINT[]),
    (500::BIGINT, 'Muy difícil. No lo lleven. Solo pasa si Saprissa es campeón.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'a59016f56d3d34cf26f48be947afdbc81d45d33304386214776ce607747f456a'::TEXT, ARRAY[1641]::BIGINT[]),
    (500::BIGINT, 'un poco confuso con el ...no da mucha variedad de ejemplos similares a lo que vienen en los exámenes'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-08-04T00:00:00+00:00'::TIMESTAMPTZ, '995643308c5ef434555d956f36980f54558682d558ee258370f06b8edd553dfd'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9ed8b75213eac591394e234d3e103adf0d4d6051c8407a7e69201016ef6d90f7'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (500::BIGINT, 'Se le entiende cuando explica. A mí me dijeron que calificaba súper fuerte, pero yo no lo vi así. No es que regale puntos, pero tampoco es imposible pasarlo. Sí lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6ddace787a940515760dce172df036a9738d6625d70d1124480398433c74068a'::TEXT, ARRAY[2920]::BIGINT[]),
    (500::BIGINT, 'Un muy buen profesor, explica bastante bien ya que sabe mucho. Hace las clases entretenidas. Si es bastante estricto calificando pero tampoco es que es imposible. Uno de los mejores profesores de la catedral de mate.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'a34817c943b4e0550b44b5efad0c9a7fd029e7fe3ab3c9e0d6e5845c0f4ab398'::TEXT, ARRAY[2444, 605, 634]::BIGINT[]),
    (500::BIGINT, 'Muy claro para explicar. Si tenés interés en la materia y ponés atención, vas a entender. Dentro del marco de referencia de los profes de cálculo, con él es fácil llevar. Fue muy comprensivo a la hora de calificar. La clase es entretenida y es muy puntual con la entrada y la salida.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '56820e49269c947a66268e4e2e8158a0094ee428f499927b50a4a524a36aed0d'::TEXT, ARRAY[2920]::BIGINT[]),
    (500::BIGINT, 'Muy buen profe, es simpático y hace la clase entretenida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'df6a6934aa8ac7e57013eec7bd500ead38531a06c64b97722f53c9aa2428ce67'::TEXT, ARRAY[2920]::BIGINT[]),
    (500::BIGINT, 'Este profesor se enreda muchas veces explicando un problema.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-28T00:00:00+00:00'::TIMESTAMPTZ, '4a5152b0a9c0986743da1acefc328e1a198b1f315fd8c114e1f27ab6bc07ee7c'::TEXT, ARRAY[1018, 1041]::BIGINT[]),
    (500::BIGINT, 'Califica con el hígado. Exlica regular y solo habla de fútbol.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'e261b8edc5fb602be2190cf72e53ee26adfec90c922bbeec4a568f6ff7a57ba4'::TEXT, ARRAY[1041]::BIGINT[]),
    (500::BIGINT, 'Demasiado buen profe, es muy inteligente, explica muy bien, demasiado simpático, hace la clase entretenida y te explica las veces que sea necesario. Super recomendado!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-09T00:00:00+00:00'::TIMESTAMPTZ, 'a6c49b1a186152cb8151a561c7e315645026a30811b63a5ba076434620c5bbc0'::TEXT, ARRAY[1034]::BIGINT[]),
    (500::BIGINT, 'Califica muy duro.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'c1d7cb15875883767b7d9b729b802a8b419e0ef31c6f58a84aae927cf3167b2c'::TEXT, ARRAY[1018]::BIGINT[]),
    (500::BIGINT, 'Saprissista envenenado!! Muy buen profe y excelente persona!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'd485a502b1a73094b12dd044d5a405fee422ccb473b6c2bf90f4bbb7477d2cb4'::TEXT, ARRAY[1632]::BIGINT[]),
    (500::BIGINT, 'Explica muy bien la materia, pero califica duro.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '83c70031bd87d62e7ed5f8cd289c7e38781063fe8b9a6586d03adeb137dd1c6d'::TEXT, ARRAY[1018]::BIGINT[]),
    (500::BIGINT, 'Es buen profesor, pero calificando es durisimo. Si sonn cursos de inicio de carrera no lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2b4c74f7201a72f46b115109fb73c6ce5952849db3637b482dcbb8f043c46c6d'::TEXT, ARRAY[1034]::BIGINT[]),
    (500::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a7c29d63f8fe86111a2e395ea9aff1e4c721d137263cecb07e8efdad1628ac5d'::TEXT, ARRAY[2920]::BIGINT[]),
    (500::BIGINT, 'El mae explica bien pero es duro calificando'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '9c9d44dc7a2f80e5a92fef86cb8f07bcc393e3547b962c13fb714a15d5a2bf3c'::TEXT, ARRAY[605]::BIGINT[]),
    (500::BIGINT, 'Para mi es malisimo!!!!, nunca matriculen con el, preferiría no llevar la materia que llevarla con el, como persona es buena gente, no explica nada y todos los ejercicios que hace nunca se entiende de donde se saca las varas.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3bf85a220ec18c3fe0d18036e417de2cc263954b70e71ea100a97a54514f4657'::TEXT, ARRAY[1018]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
